<?php declare(strict_types=1); ?>
<div class="portal-grid"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Supplier-visible communication</span><h2>Send scoped message</h2></div></header><?php if(can('supplier_portal.review')): ?><form class="form-grid" method="post" action="<?= h(app_url('supplier-portal-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="send_message"><input type="hidden" name="supplier_id" value="<?= $selectedSupplierId ?>"><label><span>Company</span><select name="company_id"><option value="0">Supplier-wide</option><?php foreach(data_permitted_companies() as $company): ?><option value="<?= (int)$company['id'] ?>"><?= h($company['name']) ?></option><?php endforeach; ?></select></label><label><span>Record type</span><select name="entity_type"><option value="supplier">Supplier</option><option value="purchase_order">Purchase order</option><option value="invoice">Invoice</option><option value="quality">Quality</option><option value="sourcing">Sourcing</option></select></label><label><span>Record ID</span><input type="number" min="0" name="entity_id" value="<?= $selectedSupplierId ?>"></label><label><span>Response due</span><input type="date" name="required_response_date"></label><label class="span-2"><span>Subject</span><input name="subject" required></label><label class="span-2"><span>Supplier-visible message</span><textarea name="message_body" rows="5" required></textarea></label><div class="span-2"><button class="button primary">Send message</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Conversation history</span><h2>Record-scoped messages</h2></div></header><div class="compact-list"><?php foreach($messages as $message): ?><article><div><strong><?= h($message['subject']) ?></strong><small><?= h(status_label($message['direction'])) ?> · <?= h(status_label($message['entity_type'])) ?> #<?= (int)$message['entity_id'] ?> · <?= h(date_us($message['created_